import sys

def main():
    cubes = list(map(int, sys.stdin.read().split()))
    if not cubes:
        return

    total = sum(cubes)
    if total % 3 != 0:
        print('N')
        return

    target = total // 3
    n = len(cubes)

    # Check if there is an index i with cubes[i] == target
    # and two distinct indices j, k != i such that cubes[j] + cubes[k] == target
    for i in range(n):
        if cubes[i] == target:
            rem = [cubes[idx] for idx in range(n) if idx != i]
            # rem has 5 elements, check if two sum to target
            found = False
            for j in range(len(rem)):
                for k in range(j + 1, len(rem)):
                    if rem[j] + rem[k] == target:
                        found = True
                        break
                if found:
                    break
            if found:
                print('S')
                return

    print('N')

if __name__ == '__main__':
    main()
